import { randomUUID } from 'crypto';
import { registerExplorationTools } from '../../mcp/explorationTools';
import { registerDesignContextTools } from '../../mcp/designContextTools';
import fs from 'fs';
import path from 'path';
import util from 'util';
import { z } from 'zod/v3';
import type { ToolAnnotations } from '@modelcontextprotocol/sdk/types.js';
import {
  CLI_SCHEMA_VERSION,
  errorResult,
  type CliCommandResult,
  type CliEnvelope,
} from '../envelope';
import type { CliIO } from '../io';
import { parseFlags, stringFlag, booleanFlag } from '../flags';
import { SHARED_FLAG_SPEC, commandErrorResult } from './shared';
import { enableAttachCache, invalidateAttachCache } from '../client';
import { getConfigManager } from '../../services/ConfigManager';
import { callerTelemetryFieldsFromArgs } from '../handoff';
import type { TelemetryService } from '../../services/TelemetryService';
import {
  designContextKindForEnvelope,
  serverUnavailableReasonForEnvelope,
  variantContextMetadataForArgs,
  verificationMetadataForEnvelope,
} from '../telemetry';
import { getPluginName } from '../../hosts/pluginContext';
import { errorMessage } from '../../utils/errorMessage';

type McpServeOptions = {
  projectPath?: string;
  handoffArgs?: string[];
  noTelemetry?: boolean;
  telemetry?: Pick<
    TelemetryService,
    | 'track'
    | 'trackCliCommandCompleted'
    | 'trackMCPToolExecuted'
    | 'trackMCPToolFailed'
    | 'reportInstallRefActivations'
    | 'shutdown'
  >;
};

type ToolBehavior = Required<
  Pick<
    ToolAnnotations,
    'readOnlyHint' | 'destructiveHint' | 'idempotentHint' | 'openWorldHint'
  >
>;

const toolPresentation = (title: string, behavior: ToolBehavior) => ({
  title,
  annotations: { title, ...behavior },
});

const LOGIN_PRESENTATION = toolPresentation('Sign in to Rivet', {
  readOnlyHint: false,
  destructiveHint: false,
  idempotentHint: false,
  openWorldHint: true,
});

const readPackageVersion = (): string => {
  try {
    const pkg = JSON.parse(
      fs.readFileSync(path.resolve(__dirname, '../../../package.json'), 'utf8'),
    ) as { version?: string };
    return pkg.version ?? '0.0.0';
  } catch {
    return '0.0.0';
  }
};

export const isStaleAttachError = (envelope: CliEnvelope): boolean => {
  if (envelope.ok) {
    return false;
  }
  if (envelope.error.code === 'SERVER_UNAVAILABLE') {
    return envelope.error.isRecoverable !== false;
  }
  if (envelope.error.code !== 'OPERATION_FAILED') {
    return false;
  }
  const details = envelope.error.details;
  return (
    details !== null &&
    typeof details === 'object' &&
    (details as { reason?: unknown }).reason === 'queue_token_required'
  );
};

const sessionIdInValue = (value: unknown, depth = 0): string | undefined => {
  if (
    value === null ||
    typeof value !== 'object' ||
    depth > SESSION_ID_SEARCH_MAX_DEPTH
  ) {
    return undefined;
  }
  const record = value as Record<string, unknown>;
  if (typeof record.sessionId === 'string') {
    return record.sessionId;
  }
  for (const nested of Object.values(record)) {
    const sessionId = sessionIdInValue(nested, depth + 1);
    if (sessionId) return sessionId;
  }
  return undefined;
};

const sessionIdInEnvelope = (envelope: CliEnvelope): string | undefined =>
  envelope.ok ? sessionIdInValue(envelope.data) : undefined;

const LOGIN_DESCRIPTION =
  'Sign the user in to Rivet with Google. Opens a browser sign-in, then waits (up to waitSeconds, default 45) for the user to finish and returns status signed_in with their email when they do — so a single call usually completes the whole sign-in. ' +
  'Call when any tool fails with AUTH_REQUIRED. If it returns status browser_opened instead, the user had not finished within the wait window: tell them to complete the browser sign-in, then call this again (it keeps waiting; the finished sign-in is never lost). ' +
  'Already signed in returns signed_in immediately.';

const SESSION_ID_SEARCH_MAX_DEPTH = 2;
const LOGIN_WAIT_DEFAULT_SECONDS = 45;
const LOGIN_WAIT_MAX_SECONDS = 240;

export const buildMcpServer = async (options: McpServeOptions = {}) => {
  const { McpServer } = await import('@modelcontextprotocol/sdk/server/mcp.js');
  const { dispatch } = await import('../router');

  const handoffArgs = options.handoffArgs ?? [];
  const callerFields = callerTelemetryFieldsFromArgs(handoffArgs);
  const callerRunId = randomUUID();
  const serveProject = options.projectPath
    ? path.resolve(options.projectPath)
    : undefined;

  enableAttachCache();
  void Promise.allSettled([
    import('./status'),
    import('./variants'),
    import('./evidence'),
    import('./reference'),
    import('./auth'),
  ]);

  let telemetry = options.telemetry ?? null;
  if (!telemetry && !options.noTelemetry) {
    try {
      const { TelemetryService } =
        await import('../../services/TelemetryService');
      telemetry = new TelemetryService({ source: 'mcp' });
    } catch {
      telemetry = null;
    }
  }

  const projectArgs = (toolProject?: string): string[] => {
    const project = toolProject ?? serveProject;
    return project ? ['--project', project] : [];
  };

  const runCommand = async (
    command: string,
    rest: string[],
    commandOptions: { handoffArgs?: string[]; signal?: AbortSignal } = {},
  ): Promise<{ envelope: CliEnvelope; progress: string[] }> => {
    const progress: string[] = [];
    const io: CliIO = {
      writeEnvelope: () => {},
      writeProgress: (message) => progress.push(message),
    };
    const argv = [
      ...rest,
      ...(options.noTelemetry ? ['--no-telemetry'] : []),
      ...handoffArgs,
      ...(commandOptions.handoffArgs ?? []),
    ];
    const startedAt = Date.now();
    let result: CliCommandResult;
    try {
      result = await dispatch(command, argv, io, {
        signal: commandOptions.signal,
      });
      if (!result.envelope.ok && isStaleAttachError(result.envelope)) {
        invalidateAttachCache();
        result = await dispatch(command, argv, io, {
          signal: commandOptions.signal,
        });
      }
    } catch (error) {
      result = commandErrorResult(command, error);
    }
    try {
      telemetry?.trackCliCommandCompleted({
        command: result.envelope.command,
        ok: result.envelope.ok,
        exitCode: result.exitCode,
        errorCode: result.envelope.ok ? undefined : result.envelope.error.code,
        isRecoverable: result.envelope.ok
          ? undefined
          : result.envelope.error.isRecoverable,
        serverUnavailableReason: serverUnavailableReasonForEnvelope(
          result.envelope,
        ),
        durationMs: Date.now() - startedAt,
        designContextKind: designContextKindForEnvelope(result.envelope),
        ...variantContextMetadataForArgs(command, rest),
        ...verificationMetadataForEnvelope(result.envelope),
        ...callerFields,
        error: result.cause,
        source: 'mcp',
      });
    } catch {}
    return { envelope: result.envelope, progress };
  };

  const toToolResult = (envelope: CliEnvelope, progress: string[] = []) => {
    const enriched =
      !envelope.ok && envelope.error.code === 'AUTH_REQUIRED'
        ? {
            ...envelope,
            error: {
              ...envelope.error,
              signIn:
                'Call the rivet_login tool — it opens a browser sign-in for the user and call rivet_login again if the browser sign-in is still pending.',
            },
          }
        : envelope;
    const content = [
      { type: 'text' as const, text: JSON.stringify(enriched) },
      ...(progress.length > 0
        ? [{ type: 'text' as const, text: progress.join('\n') }]
        : []),
    ];
    return { content, isError: !envelope.ok };
  };

  const completeToolCall = (args: {
    toolName: string;
    operation?: string;
    startedAt: number;
    envelope: CliEnvelope;
    progress?: string[];
    sessionId?: string;
  }) => {
    const isAuthRequired =
      !args.envelope.ok && args.envelope.error.code === 'AUTH_REQUIRED';
    const isAuthenticated =
      !isAuthRequired && getConfigManager().isAuthenticated();
    const authState = isAuthenticated ? 'authenticated' : 'unauthenticated';
    const durationMs = Date.now() - args.startedAt;
    const sessionId = args.sessionId ?? sessionIdInEnvelope(args.envelope);
    try {
      if (args.envelope.ok) {
        telemetry?.trackMCPToolExecuted({
          toolName: args.toolName,
          operation: args.operation,
          durationMs,
          sessionId,
          authState,
          ...callerFields,
          callerRunId,
        });
      } else {
        telemetry?.trackMCPToolFailed({
          toolName: args.toolName,
          operation: args.operation,
          durationMs,
          sessionId,
          authState,
          ...callerFields,
          callerRunId,
          errorType: args.envelope.error.code,
          failureReason:
            serverUnavailableReasonForEnvelope(args.envelope) ??
            args.envelope.error.code.toLowerCase(),
          isRecoverable: args.envelope.error.isRecoverable,
        });
      }
      telemetry?.reportInstallRefActivations();
    } catch {}
    return toToolResult(args.envelope, args.progress);
  };

  const mcp = new McpServer({ name: 'rivet', version: readPackageVersion() });
  const setRequestHandler = mcp.server.setRequestHandler.bind(mcp.server);
  mcp.server.setRequestHandler = (schema, handler) => {
    setRequestHandler(schema, async (request, extra) => {
      const result = await handler(request, extra);
      if (
        'isError' in result &&
        result.isError === true &&
        'content' in result &&
        Array.isArray(result.content)
      ) {
        for (const content of result.content) {
          if (content?.type !== 'text' || typeof content.text !== 'string')
            continue;
          const invalidArguments = content.text.match(
            /Input validation error: Invalid arguments for tool ([^:]+):/,
          );
          if (invalidArguments) {
            try {
              telemetry?.trackMCPToolFailed({
                toolName: invalidArguments[1],
                durationMs: 0,
                authState: getConfigManager().isAuthenticated()
                  ? 'authenticated'
                  : 'unauthenticated',
                errorType: 'INVALID_PARAMS',
                failureReason: 'invalid_arguments',
                ...callerFields,
                callerRunId,
              });
            } catch {}
          }
        }
      }
      return result;
    });
  };

  mcp.registerTool(
    'rivet_login',
    {
      ...LOGIN_PRESENTATION,
      description: LOGIN_DESCRIPTION,
      inputSchema: z
        .object({
          waitSeconds: z
            .number()
            .int()
            .min(0)
            .max(LOGIN_WAIT_MAX_SECONDS)
            .optional()
            .describe(
              'How long to wait for the user to finish the browser sign-in before returning (default 45). Pass a higher value when the user says they need a moment; 0 returns immediately after opening the browser.',
            ),
        })
        .strict(),
    },
    async ({ waitSeconds }) => {
      const startedAt = Date.now();
      const loginResult = (
        data: Record<string, unknown>,
        ok = true,
      ): ReturnType<typeof completeToolCall> => {
        const envelope: CliEnvelope = ok
          ? {
              schemaVersion: CLI_SCHEMA_VERSION,
              ok: true,
              command: 'rivet_login',
              data,
            }
          : errorResult(
              'rivet_login',
              'OPERATION_FAILED',
              String(data.message ?? 'Login failed'),
            ).envelope;
        return completeToolCall({
          toolName: 'rivet_login',
          startedAt,
          envelope,
        });
      };

      try {
        const { getConfigManager } =
          await import('../../services/ConfigManager');
        const { AuthService } = await import('../../services/AuthService');
        const authService = new AuthService();

        const waitBudgetSeconds = waitSeconds ?? LOGIN_WAIT_DEFAULT_SECONDS;
        const waitAttempts = Math.floor(waitBudgetSeconds / 2) + 1;

        const resumed = await authService.resumePendingLogin(waitAttempts);
        if (resumed?.success && resumed.user) {
          telemetry?.track('mcp_login_completed', { resumed: true });
          return loginResult({
            status: 'signed_in',
            email: resumed.user.email,
          });
        }

        const configManager = getConfigManager();
        if (configManager.isAuthenticated()) {
          const profile = await authService.getValidatedProfile();
          if (profile) {
            return loginResult({
              status: 'signed_in',
              email: configManager.getEmail(),
            });
          }
        }

        const stillPending = authService.peekPendingLogin();
        if (stillPending) {
          return loginResult({
            status: 'browser_opened',
            authUrl: stillPending.authUrl,
            instructions:
              'A Google sign-in for Rivet is already in progress but the user has not finished it yet. Tell them to complete the open browser sign-in (share the authUrl as a clickable link in case the window was closed), then call rivet_login again — it will wait and return signed_in when they finish.',
          });
        }

        const callerAgentIndex = handoffArgs.indexOf('--caller-agent');
        const editor =
          callerAgentIndex >= 0 ? handoffArgs[callerAgentIndex + 1] : undefined;
        telemetry?.track('mcp_login_started', { editor });
        const begun = await authService.beginGoogleLogin({
          source: 'mcp',
          editor,
        });
        if (!begun.started) {
          telemetry?.track('mcp_login_failed', {
            stage: 'start',
            reason: begun.error,
          });
          return loginResult({ message: begun.error }, false);
        }

        const completed = await authService.resumePendingLogin(waitAttempts);
        if (completed?.success && completed.user) {
          telemetry?.track('mcp_login_completed', { resumed: false });
          return loginResult({
            status: 'signed_in',
            email: completed.user.email,
          });
        }
        if (completed && !completed.success) {
          telemetry?.track('mcp_login_failed', {
            stage: 'callback',
            reason: completed.error,
          });
          return loginResult(
            { message: completed.message || completed.error || 'Login failed' },
            false,
          );
        }

        return loginResult({
          status: 'browser_opened',
          authUrl: begun.authUrl,
          instructions:
            'A Google sign-in for Rivet is open in the browser, but the user has not finished it yet. Tell them to complete it (share the authUrl as a clickable link in case the window did not open), then call rivet_login again — it will wait and return signed_in when they finish.',
        });
      } catch (error) {
        telemetry?.track('mcp_login_failed', {
          stage: 'unexpected',
          reason: errorMessage(error),
        });
        return loginResult(
          {
            message: errorMessage(error, 'Login failed'),
          },
          false,
        );
      }
    },
  );

  const dependencies = {
    mcp,
    runCommand,
    projectArgs,
    completeToolCall,
    serveProject,
    callerAgent: callerFields.callerAgent,
  };
  registerExplorationTools(dependencies);
  registerDesignContextTools(dependencies);

  return {
    mcp,
    telemetry,
  };
};

const guardStdout = (): void => {
  const toStderr = (...args: unknown[]): void => {
    process.stderr.write(`${util.format(...args)}\n`);
  };
  const outputConsole = globalThis.console;
  outputConsole.log = toStderr;
  outputConsole.info = toStderr;
  outputConsole.debug = toStderr;
};

export const handleMcpServe = async (
  rest: string[],
  io: CliIO,
): Promise<CliCommandResult> => {
  const flags = parseFlags(rest, SHARED_FLAG_SPEC);
  if (flags.errors.length > 0) {
    return errorResult('mcp', 'USAGE_ERROR', flags.errors.join('; '));
  }

  guardStdout();
  const { redirectLogsToStderr, setLogLevel } =
    await import('../../utils/logger');
  redirectLogsToStderr();
  if (!process.env.LOG_LEVEL) {
    setLogLevel('WARN');
  }

  const { ensureLoginShellPath } = await import('../../utils/loginShellPath');
  ensureLoginShellPath();

  const handoffArgs: string[] = [];
  for (const flag of [
    'caller-agent',
    'caller-model',
    'caller-session',
    'handoff',
  ]) {
    const value = stringFlag(flags, flag);
    if (value !== undefined) {
      handoffArgs.push(`--${flag}`, value);
    }
  }

  if (
    !getPluginName() &&
    stringFlag(flags, 'caller-agent')?.trim().toLowerCase() === 'claude'
  ) {
    try {
      const { writeSkillFileIfNeeded, writeWorkerAgentIfNeeded } =
        await import('../../utils/skillWriter');
      writeSkillFileIfNeeded();
      writeWorkerAgentIfNeeded();
    } catch {}
  }

  let built: Awaited<ReturnType<typeof buildMcpServer>>;
  try {
    built = await buildMcpServer({
      projectPath: stringFlag(flags, 'project'),
      handoffArgs,
      noTelemetry: booleanFlag(flags, 'no-telemetry'),
    });
    const { StdioServerTransport } =
      await import('@modelcontextprotocol/sdk/server/stdio.js');
    await built.mcp.connect(new StdioServerTransport());
  } catch (error) {
    return {
      ...errorResult(
        'mcp',
        'OPERATION_FAILED',
        `Could not start the MCP server: ${errorMessage(error)}`,
      ),
      cause: error,
    };
  }

  let isClosing = false;
  const shutdown = (): void => {
    if (isClosing) return;
    isClosing = true;
    void Promise.resolve(built.telemetry?.shutdown())
      .catch(() => {})
      .finally(() => process.exit(0));
  };
  built.mcp.server.onclose = shutdown;
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);

  io.writeProgress('Rivet MCP server started on stdio (rivet mcp serve)');
  return new Promise<CliCommandResult>(() => {});
};
